-- Bimal Pathology complete 256-test identity master.
-- Identity/profile structure only: no prices, ranges, formulas, methods, analyzers or clinical activation.


CREATE TYPE public.catalogue_reporting_model_enum AS ENUM ('NumericSingle','NumericMultiParameter','Qualitative','MixedTyped','StructuredNested','NarrativeDocument','Calculated','Profile','MicrobiologyWorkflow','CytologyWorkflow','MolecularWorkflow');

CREATE TYPE public.catalogue_source_disposition_enum AS ENUM ('CanonicalStandaloneTest','CanonicalProfile','ProfileComponentOnly','AliasOnly','DuplicateDoNotCreate','DraftNewIdentity','SpecialistWorkflow','ConflictNeedsOperatorDecision','RetireCandidate');

ALTER TABLE public.tests ADD COLUMN reporting_model public.catalogue_reporting_model_enum DEFAULT 'NumericSingle';

UPDATE public.tests t SET reporting_model=CASE WHEN t.test_kind='Profile' THEN 'Profile'::public.catalogue_reporting_model_enum WHEN t.workflow_type='MicrobiologyCulture' THEN 'MicrobiologyWorkflow'::public.catalogue_reporting_model_enum WHEN t.workflow_type='Cytology' THEN 'CytologyWorkflow'::public.catalogue_reporting_model_enum WHEN t.workflow_type='Molecular' THEN 'MolecularWorkflow'::public.catalogue_reporting_model_enum WHEN t.reporting_type='NoReporting' THEN 'NarrativeDocument'::public.catalogue_reporting_model_enum WHEN EXISTS(SELECT 1 FROM public.parameters p WHERE p.test_id=t.id AND p.is_active AND p.value_type='Select') THEN 'Qualitative'::public.catalogue_reporting_model_enum WHEN (SELECT count(*) FROM public.parameters p WHERE p.test_id=t.id AND p.is_active)>1 THEN 'NumericMultiParameter'::public.catalogue_reporting_model_enum ELSE 'NumericSingle'::public.catalogue_reporting_model_enum END;

ALTER TABLE public.tests ALTER COLUMN reporting_model SET NOT NULL;

CREATE TABLE public.catalogue_master_sources(id UUID PRIMARY KEY,source_name TEXT NOT NULL,source_version TEXT NOT NULL,source_sha256 CHAR(64) NOT NULL,source_row_count INT NOT NULL CHECK(source_row_count=256),imported_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(source_name,source_version));

CREATE TABLE public.catalogue_identity_conflicts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),conflict_key TEXT NOT NULL UNIQUE,title TEXT NOT NULL,source_numbers INT[] NOT NULL,canonical_code TEXT,status TEXT NOT NULL DEFAULT 'Open' CHECK(status IN('Open','Resolved','Rejected')),recommendation TEXT NOT NULL,resolution JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),resolved_at TIMESTAMPTZ,resolved_by UUID REFERENCES auth.users(id));

CREATE TABLE public.catalogue_master_source_rows(source_id UUID NOT NULL REFERENCES public.catalogue_master_sources(id),source_number INT NOT NULL CHECK(source_number BETWEEN 1 AND 256),source_name TEXT NOT NULL,source_alias TEXT,source_type TEXT NOT NULL,source_department TEXT NOT NULL,canonical_department TEXT NOT NULL,disposition public.catalogue_source_disposition_enum NOT NULL,reporting_model public.catalogue_reporting_model_enum NOT NULL,canonical_code TEXT,canonical_test_id UUID REFERENCES public.tests(id),canonical_parameter_id UUID REFERENCES public.parameters(id),conflict_id UUID REFERENCES public.catalogue_identity_conflicts(id),provenance JSONB NOT NULL,PRIMARY KEY(source_id,source_number));

CREATE TABLE public.catalogue_profile_components(profile_test_id UUID NOT NULL REFERENCES public.tests(id) ON DELETE RESTRICT,component_test_id UUID REFERENCES public.tests(id) ON DELETE RESTRICT,component_parameter_id UUID REFERENCES public.parameters(id) ON DELETE RESTRICT,component_role TEXT NOT NULL CHECK(component_role IN('Measured','Calculated','Qualitative','ComponentService')),display_order INT NOT NULL,is_required BOOLEAN NOT NULL DEFAULT true,source_numbers INT[] NOT NULL DEFAULT '{}',PRIMARY KEY(profile_test_id,display_order),CHECK((component_test_id IS NOT NULL)::INT+(component_parameter_id IS NOT NULL)::INT=1),UNIQUE(profile_test_id,component_test_id),UNIQUE(profile_test_id,component_parameter_id));

ALTER TABLE public.catalogue_master_sources ENABLE ROW LEVEL SECURITY; ALTER TABLE public.catalogue_master_source_rows ENABLE ROW LEVEL SECURITY; ALTER TABLE public.catalogue_identity_conflicts ENABLE ROW LEVEL SECURITY; ALTER TABLE public.catalogue_profile_components ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.catalogue_master_sources,public.catalogue_master_source_rows,public.catalogue_identity_conflicts,public.catalogue_profile_components FROM PUBLIC,anon,authenticated; GRANT SELECT ON public.catalogue_master_sources,public.catalogue_master_source_rows,public.catalogue_identity_conflicts,public.catalogue_profile_components TO authenticated; CREATE POLICY catalogue_master_manager_read ON public.catalogue_master_sources FOR SELECT TO authenticated USING(public.has_permission('can_manage_catalogue')); CREATE POLICY catalogue_rows_manager_read ON public.catalogue_master_source_rows FOR SELECT TO authenticated USING(public.has_permission('can_manage_catalogue')); CREATE POLICY catalogue_conflicts_manager_read ON public.catalogue_identity_conflicts FOR SELECT TO authenticated USING(public.has_permission('can_manage_catalogue')); CREATE POLICY catalogue_profile_components_read ON public.catalogue_profile_components FOR SELECT TO authenticated USING(public.is_active_user());

CREATE OR REPLACE FUNCTION public.reject_catalogue_master_evidence_mutation() RETURNS TRIGGER LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN RAISE EXCEPTION 'Catalogue master source evidence is immutable.' USING ERRCODE='55000'; END $$; CREATE TRIGGER catalogue_master_sources_immutable BEFORE UPDATE OR DELETE ON public.catalogue_master_sources FOR EACH ROW EXECUTE FUNCTION public.reject_catalogue_master_evidence_mutation(); CREATE TRIGGER catalogue_master_rows_immutable BEFORE UPDATE OR DELETE ON public.catalogue_master_source_rows FOR EACH ROW EXECUTE FUNCTION public.reject_catalogue_master_evidence_mutation();







































































































































































