UPDATE public.tests SET test_kind='Profile',reporting_model='Profile' WHERE code IN('CBC','DLC','LFT','KFT','LIPID_PROFILE','THYROID_PROFILE','THYROID_ECLIA','ABS_DLC','RBC_INDICES','PLATELET_INDICES','DENGUE_PANEL','DENGUE_IGM_IGG_PANEL');

UPDATE public.tests SET billing_enabled=false,clinical_reporting_enabled=false,clinical_configuration_status='Requires Clinical Validation',configuration_notes=concat_ws(' ',configuration_notes,'TM256 convergence: structurally incomplete legacy identity held non-operational pending canonical resolution.') WHERE code IN('AFP','BETA HCG','LIPID','RFT') AND NOT EXISTS(SELECT 1 FROM public.parameters p WHERE p.test_id=tests.id AND p.is_active AND p.lifecycle_status='Active');

UPDATE public.tests SET clinical_reporting_enabled=false,clinical_configuration_status=CASE WHEN clinical_configuration_status='Configured' THEN 'Requires Clinical Validation'::public.clinical_configuration_status_enum ELSE clinical_configuration_status END,configuration_notes=concat_ws(' ',configuration_notes,'TM256 safety convergence: clinical reporting is disabled until an active parameter structure exists.') WHERE clinical_reporting_enabled AND NOT EXISTS(SELECT 1 FROM public.parameters p WHERE p.test_id=tests.id AND p.is_active AND p.lifecycle_status='Active');

UPDATE public.tests t SET category_id=c.id,category=c.name FROM public.test_categories c WHERE c.code='CLINICAL_PATHOLOGY' AND t.code IN('STOOL_OB','STOOL_RE','URINE_RE') AND t.category_id IS NULL;





























































































































































































































































































































































CREATE OR REPLACE FUNCTION public.catalogue_expand_profile(p_profile_test_id UUID) RETURNS TABLE(component_test_id UUID,component_parameter_id UUID,component_role TEXT,display_order INT,is_required BOOLEAN) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT c.component_test_id,c.component_parameter_id,c.component_role,c.display_order,c.is_required FROM public.catalogue_profile_components c JOIN public.tests p ON p.id=c.profile_test_id WHERE c.profile_test_id=p_profile_test_id AND p.test_kind='Profile' ORDER BY c.display_order $$; REVOKE ALL ON FUNCTION public.catalogue_expand_profile(UUID) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.catalogue_expand_profile(UUID) TO authenticated;

DO $$ DECLARE n INT; BEGIN SELECT count(*) INTO n FROM public.catalogue_master_source_rows WHERE source_id='25600000-0000-0000-0000-000000000001'; IF n<>256 THEN RAISE EXCEPTION 'TM256_ACCOUNTING_FAILED: expected 256 rows, got %',n; END IF; IF EXISTS(SELECT 1 FROM public.tests GROUP BY upper(code) HAVING count(*)>1) THEN RAISE EXCEPTION 'TM256_DUPLICATE_CODE'; END IF; IF EXISTS(SELECT 1 FROM public.tests WHERE lifecycle_status='Draft' AND (is_active OR billing_enabled OR clinical_reporting_enabled)) THEN RAISE EXCEPTION 'TM256_DRAFT_OPERATIONAL'; END IF; IF EXISTS(SELECT 1 FROM public.tests t WHERE t.clinical_reporting_enabled AND NOT EXISTS(SELECT 1 FROM public.parameters p WHERE p.test_id=t.id AND p.is_active AND p.lifecycle_status='Active')) THEN RAISE EXCEPTION 'TM256_REPORTING_WITHOUT_STRUCTURE'; END IF; IF EXISTS(SELECT 1 FROM public.tests WHERE reporting_model IN('MicrobiologyWorkflow','CytologyWorkflow','MolecularWorkflow','StructuredNested') AND workflow_supported AND clinical_reporting_enabled) THEN RAISE EXCEPTION 'TM256_SPECIALIST_GENERIC_REPORTING'; END IF; IF EXISTS(SELECT 1 FROM public.catalogue_profile_components c LEFT JOIN public.tests p ON p.id=c.profile_test_id WHERE p.id IS NULL) THEN RAISE EXCEPTION 'TM256_ORPHAN_PROFILE_COMPONENT'; END IF; END $$;
