INSERT INTO public.parameters(test_id,code,name,value_type,unit,display_order,is_mandatory,is_active,lifecycle_status,clinical_configuration_status,unit_validation_required,range_validation_required,method_validation_required) SELECT t.id,v.code,v.name,v.value_type::public.parameter_value_type_enum,NULL,v.ord,true,false,'Draft','Requires Clinical Validation',true,true,true FROM public.tests t CROSS JOIN (VALUES ('ANC','Absolute Neutrophil Count','Calculated',1),('ALC','Absolute Lymphocyte Count','Calculated',2),('AMC','Absolute Monocyte Count','Calculated',3),('AEC','Absolute Eosinophil Count','Calculated',4),('ABC','Absolute Basophil Count','Calculated',5))v(code,name,value_type,ord) WHERE t.code='ABS_DLC' AND NOT EXISTS(SELECT 1 FROM public.parameters p WHERE p.test_id=t.id AND p.code=v.code);
