INSERT INTO public.catalogue_master_source_rows(source_id,source_number,source_name,source_alias,source_type,source_department,canonical_department,disposition,reporting_model,canonical_code,canonical_test_id,canonical_parameter_id,conflict_id,provenance) SELECT '25600000-0000-0000-0000-000000000001',256,'Mantoux test',NULL,'Document','Miscellaneous','Miscellaneous','DraftNewIdentity'::public.catalogue_source_disposition_enum,'StructuredNested'::public.catalogue_reporting_model_enum,'MANTOUX_TEST',t.id,p.id,c.id,jsonb_build_object('existing_lis_match','','reconciliation_match_type','MissingDraftCandidate','workflow','Document/StructuredNarrativeReview','conflict','','required_next_action','review conflict/identity, then create Draft with billing/reporting disabled only if approved') FROM (SELECT 1) seed LEFT JOIN public.tests t ON t.code='MANTOUX_TEST' LEFT JOIN LATERAL(SELECT px.id FROM public.parameters px WHERE px.test_id=t.id AND (lower(px.name)=lower('Mantoux test') OR lower(px.code)=lower('Mantoux test')) ORDER BY px.display_order LIMIT 1)p ON true LEFT JOIN public.catalogue_identity_conflicts c ON c.conflict_key='TM256-256';
